1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Household duplicate detection for create-owner — "the duplicate block". Duplicate detection keys off
10	 * the household, which is now the deterministic {@link HouseholdId} derived from the last name and
11	 * postcode: two owners belong to the same household exactly when they share a {@code householdId}.
12	 * Because the household is keyed on {@code (lastName, postcode)}, a second owner matching an existing
13	 * owner's last name and postcode is a household duplicate and is rejected via
14	 * {@link DuplicateIdentityException}, which the global handler turns into a 409.
15	 *
16	 * <p>A request that sets {@code sharesHousehold} true bypasses this block: it is a declared household
17	 * member and is created (see {@link DetectPossibleDuplicate}, which does not flag a declared member as a
18	 * suspected duplicate). {@code sharesHousehold} now only bypasses the duplicate block; the shared
19	 * {@code householdId} is derived automatically, not linked. Runs before the owner is built and saved,
20	 * so {@link OwnerRepository#findAll()} sees only the owners that existed before this create.
21	 */
22	public class RejectDuplicateOwner {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return; // declared household member — bypass the duplicate block
28	        }
29	        String householdId = HouseholdId.of(request.getLastName(), request.getPostcode());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (Boolean.TRUE.equals(existing.getDeleted())) {
32	                continue; // soft-deleted owners are ignored by the duplicate check
33	            }
