7	
8	/**
9	 * Assigns the {@code membershipPoints} score and the derived numeric {@code membershipLevel} at
10	 * creation time. Points start at {@code 0} and accrue: {@code 2} when the owner has an email,
11	 * {@code 1} when {@code namesakeCount} is {@code 0}, {@code 2} for a household of {@code 3} or more
12	 * (from {@code householdSize}), and {@code 3} for a tenure of at least one elapsed fiscal year
13	 * (fiscal years, starting 1 July, between the owner's {@code registrationDate} and the current
14	 * server date). Points map to a level as {@code 1} (0-1 points), {@code 2} (2-3), {@code 3} (4-5)
15	 * and {@code 4} (6 or more). Runs after {@link CountNamesakes} and {@link CountHousehold} so both
16	 * counts are already set.
17	 */
18	public class AssignMembershipLevel {
19	
20	    /** Elapsed fiscal years at or above which the owner qualifies for the tenure points. */
21	    private static final int TENURE_THRESHOLD_FISCAL_YEARS = 1;
22	
23	    /** Household size at or above which the household points are awarded. */
24	    private static final int HOUSEHOLD_THRESHOLD = 3;
25	
26	    public void service(@Val Owner owner) {
27	        int points = 0;
28	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
29	            points += 2;
30	        }
31	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
32	            points += 1;
33	        }
34	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
35	            points += 2;
36	        }
37	        if (tenureFiscalYears(owner) >= TENURE_THRESHOLD_FISCAL_YEARS) {
38	            points += 3;
39	        }
40	        owner.setMembershipPoints(points);
41	        owner.setMembershipLevel(levelForPoints(points));
42	    }
43	
44	    private static int levelForPoints(int points) {
45	        if (points <= 1) {
46	            return 1;
47	        }
48	        if (points <= 3) {
49	            return 2;
50	        }
51	        if (points <= 5) {
52	            return 3;
53	        }
54	        return 4;
55	    }
56	
57	    private static int tenureFiscalYears(Owner owner) {
58	        LocalDate registrationDate = owner.getRegistrationDate();
59	        if (registrationDate == null) {
60	            return 0;
61	        }
62	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
63	    }
64	}
